{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陆时",
      "role": "protagonist",
      "identity": "狂躁症患者、超忆症患者",
      "traits": ["偏执隐忍", "记忆力超群", "控制欲强", "感情纯粹"],
      "overt_motivation": "每天重新追求苏晚，配合医院的配对治疗实验",
      "covert_motivation": "永远把苏晚留在自己身边，获得不会变质消失的纯粹爱情",
      "secret_fear": "苏晚恢复全部记忆后会想起车祸的真相，彻底离开自己",
      "misperception_of_other": "认为苏晚只有在失忆状态下的爱意才是不带任何世俗杂质的，是最真实的",
      "hidden_connection": "三年前苏晚是他的女友，苏晚的失忆正是因为当时为了救狂躁症发作跑到马路上的他而遭遇车祸"
    },
    {
      "name": "苏晚",
      "role": "deuteragonist",
      "identity": "抑郁症患者、顺行性失忆症患者",
      "traits": ["敏感温柔", "缺乏安全感", "共情力强", "骨子里执拗"],
      "overt_motivation": "每天配合医生治疗，对每天出现的陌生男生产生好感并爱上他",
      "covert_motivation": "想要找回丢失的记忆碎片，获得稳定不会消失的感情归属",
      "secret_fear": "自己丢失的记忆里藏着无法承受的痛苦过往",
      "misperception_of_other": "以为陆时和自己一样是记不住前一天事情的普通病人，不知道他记得所有相处的细节",
      "hidden_connection": "车祸后潜意识里仍然保留着对陆时的好感，所以才会每天都重新爱上他"
    }
  ],
  "supporting_characters": [
    {
      "name": "陈默",
      "function": "阻碍",
      "identity": "精神科主治医生、配对治疗实验负责人",
      "description": "表面温和负责，实则为了学术成果秘密开展精神病患配对观察实验，手握陆时和苏晚过去的全部资料，默许了陆时刻意引导苏晚依赖的行为"
    }
  ],
  "relationship_dynamics": "陆时凭借超忆的优势在精神病院每日记忆重置的规则里反复追求苏晚，两人在被医生观察的实验环境里滋生出真实的爱意，陈默作为规则制定者掌握着两人的命运，苏晚意外恢复记忆的事件打破了所有人的计划，最终将爱情推向了自愿沉沦的悲剧性稳态。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立精神病院每日记忆重置的核心规则，引入陆时、苏晚和陈默三个核心角色，展示两人日常的互动模式，埋下秘密实验和过往关联的伏笔，篇幅约1500字。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "白色房间的早安",
        "core_event": "苏晚在纯白色的病房醒来，失去了前一天的所有记忆，陆时按照惯例带着向日葵出现在她的病房门口，开始新一天的追求，主治医生陈默送来两人的药和空白的病历本。",
        "emotional_tone": "平淡柔和中暗藏隐秘的甜意",
        "key_scenes": [
          "苏晚醒来看见床头柜上空无一字的病历本",
          "陆时指尖带着薄茧，把向日葵插到苏晚床头的玻璃瓶里",
          "陈默穿着白大褂，叮嘱两人按时吃药不要随便离开病区",
          "陆时回到自己病房，在墙角落下的刻痕上添了新的一笔"
        ]
      }
    ],
    "turning_point": "苏晚帮陆时捡掉在地上的外套时，无意间摸到他口袋里有一张折得很旧的两人合影，照片上的她笑得很开心。"
  },
  "act_two": {
    "description": "两人互动逐渐加深，苏晚对医院的规则和自己的过往产生越来越深的怀疑，陈默的实验目的和陆时的秘密逐步暴露，冲突持续升级，篇幅约3500字。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "重复的告白",
        "core_event": "陆时带着苏晚在医院的小花园约会，给她讲很多细节丰富的"小故事"，苏晚第一次对医院"每天清零记忆帮助治疗"的说法产生怀疑，偷偷把陈默给的药藏了起来没有吃。",
        "emotional_tone": "甜中带涩，疑惑感逐步加重",
        "key_scenes": [
          "陆时准确说出苏晚喜欢吃三分糖的冰粉，不喜欢吃香菜，苏晚感到诧异",
          "苏晚翻看病历本，发现夹层里夹着陆时写的情书，字迹已经有些褪色",
          "陈默找到陆时，警告他不要透露实验的真实内容，否则就把两人分开",
          "苏晚在卫生间把药片吐到了马桶里冲掉"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "墙后的刻痕",
        "core_event": "苏晚因为没有吃药，第一次完整保留了前一天的记忆，半夜听见隔壁陆时的房间有刻东西的声音，偷偷过去查看，发现满墙都是"今天她笑了X次"的刻痕，还听见了陆时和陈默的谈话，知道了配对治疗其实是观察实验，以及陆时拥有超忆症的真相。",
        "emotional_tone": "震惊、压抑，寒意逐渐渗透",
        "key_scenes": [
          "苏晚凌晨三点醒过来，清晰记得前一天陆时说过的每一句话",
          "苏晚推开陆时没有锁的病房门，月光下满墙的刻痕密密麻麻",
          "苏晚在陆时的枕头底下发现了两人三年前的完整相册",
          "苏晚躲在走廊拐角，听见陈默说"如果她恢复记忆，实验就终止"的对话"
        ]
      }
    ],
    "turning_point": "苏晚靠在冰冷的墙壁上，确认自己没有失忆，这一周所有和陆时相处的记忆都清晰地刻在脑子里。"
  },
  "act_three": {
    "description": "真相彻底大白，三人对峙，苏晚做出最终选择，故事定格在病态浪漫的新稳态，回扣所有核心物件，篇幅约3000字。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "疯子的爱情",
        "core_event": "第二天苏晚没有假装失忆，拿出所有证据和陆时对质，陆时坦白了所有秘密，包括三年前的车祸真相，陈默出现要终止实验送苏晚出院，苏晚最终选择自愿留在精神病院，让陆时第二天继续追她。",
        "emotional_tone": "撕裂、释然，病态的浪漫达到顶峰",
        "key_scenes": [
          "陆时看见苏晚拿出旧相册，放弃辩解，坦白自己故意引导她产生依赖的全部事实",
          "陈默拿着实验报告和出院通知，要求苏晚立刻办理手续离开",
          "苏晚摸着陆时指尖因为刻墙留下的密密麻麻的伤疤",
          "苏晚把自己的病历本和陆时的钉在一起，扔进了陈默的垃圾桶，笑着说"那你明天记得再追我一次""
        ]
      }
    ],
    "turning_point": "陆时愣了几秒，低下头笑得眼泪都掉了下来，重重地点了点头。"
  }
}"}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "x_axis_display": {
          "type": "string",
          "description": "X轴模式在故事中的具体显影方式"
        },
        "y_axis_combination_effect": {
          "type": "string",
          "description": "Y轴标签组合产生的效应描述"
        },
        "reaction_formula": {
          "type": "string",
          "description": "化学反应公式的一句话描述"
        },
        "platform_fit": {
          "type": "array",
          "description": "适合发布的平台类型",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "one_sentence_synopsis": {
      "type": "string",
      "description": "一句话故事梗概（30-50字）",
      "minLength": 30,
      "maxLength": 50
    }
  }
}

